//! Checks that README.md and doc/wiki/*.md, generated by `satex-doc` from
//! the templates in doc/src, are up to date with what's checked in.

use std::fs;
use std::process::Command;

use regex::Regex;

#[test]
fn generated_docs_are_up_to_date() {
    let manifest_dir = env!("CARGO_MANIFEST_DIR");
    let output = Command::new(env!("CARGO_BIN_EXE_satex-doc"))
        .arg("--check")
        // `satex-doc` runs real commands, against the binary of this profile.
        .env("SATEX_DOC_BIN", env!("CARGO_BIN_EXE_satex"))
        .current_dir(manifest_dir)
        .output()
        .expect("failed to run satex-doc");

    assert!(
        output.status.success(),
        "README.md and doc/wiki/*.md are stale; regenerate with \
         `cargo run --release --features doc --bin satex-doc`\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
}

/// Every generated page `satex-doc` writes, so a page added to `TEMPLATES`
/// there needs no separate addition here to be covered.
const GENERATED_PAGES: &[&str] = &[
    "README.md",
    "doc/wiki/lints.md",
    "doc/wiki/queries.md",
    "doc/wiki/configuration.md",
    "doc/wiki/lsp.md",
    "doc/wiki/domains.md",
    "doc/chktex-coverage.md",
    "doc/wiki/primitive-coverage.md",
];

/// Replaces every match of `re` with spaces (newlines kept as newlines), so
/// a later scan sees the same offsets and line numbers as the original text
/// but none of the masked content.
fn mask(text: &str, re: &Regex) -> String {
    let mut out = String::with_capacity(text.len());
    let mut last = 0;
    for m in re.find_iter(text) {
        out.push_str(&text[last..m.start()]);
        out.extend(m.as_str().chars().map(|c| if c == '\n' { '\n' } else { ' ' }));
        last = m.end();
    }
    out.push_str(&text[last..]);
    out
}

/// `satex-doc`'s `linkify_citations` turns every citation of an
/// authoritative source (`tex.web § 211`, `[LuaTeX manual, "Macros"]`, a
/// bare `Source: ChkTeX 1.7.9 manual, § 8`) into a markdown link, so a
/// reader can check the claim instead of taking satex's word for it. This
/// guards against a new citation form reaching a generated page that the
/// linker does not recognize and so leaves as bare text: a fenced code
/// block, an inline code span, and the label of an existing link are
/// masked out first, and what's left must contain neither a `§` nor one of
/// the source names that only ever appear here as a citation.
#[test]
fn generated_docs_have_no_bare_citations() {
    let fence_re = Regex::new(r"(?s)```.*?```").unwrap();
    let link_re = Regex::new(r"\[[^\]]*\]\([^)]*\)").unwrap();
    let code_re = Regex::new(r"`[^`]*`").unwrap();
    let section_re = Regex::new("§").unwrap();

    // Names that, in these docs, are never an ordinary word: every mention
    // is a citation, so `linkify_citations` links every one of them, with
    // or without a section after it. A package name that doubles as
    // ordinary prose (`xcolor`, `chktex`, `latexmk`, ...) is deliberately
    // left out: it is only a citation when followed by a `§`, which the
    // `section_re` check above already covers.
    let distinctive_sources = [
        "tex.web",
        "The TeXbook",
        "source2e",
        "fntguide",
        "usrguide",
        "clsguide",
        "interface3",
        "l2tabu",
        "The LaTeX Companion",
        "btxdoc",
        "pdfTeX manual",
        "LuaTeX manual",
        "PDF 32000",
        "SI brochure",
        "TeX Live manual",
        "MiKTeX manual",
        "ChkTeX",
        "eTeX manual",
        "etex_man",
        "XeTeX reference",
    ];
    let name_res: Vec<Regex> =
        distinctive_sources.iter().map(|name| Regex::new(&format!(r"\b{}\b", regex::escape(name))).unwrap()).collect();

    for page in GENERATED_PAGES {
        let text = fs::read_to_string(page).unwrap_or_else(|e| panic!("{page}: {e}"));
        let masked = mask(&text, &fence_re);
        let masked = mask(&masked, &link_re);
        let masked = mask(&masked, &code_re);

        if let Some(m) = section_re.find(&masked) {
            let line = masked[..m.start()].matches('\n').count() + 1;
            let context = text.lines().nth(line - 1).unwrap_or_default().trim();
            panic!(
                "{page}:{line}: bare citation `{context}` (a `§` outside any markdown link); \
                 regenerate with `cargo run --release --features doc --bin satex-doc`, and if it \
                 is still bare after that, `linkify_citations` in src/bin/satex-doc.rs needs to \
                 learn this citation's shape"
            );
        }
        for (name, re) in distinctive_sources.iter().zip(&name_res) {
            if let Some(m) = re.find(&masked) {
                let line = masked[..m.start()].matches('\n').count() + 1;
                let context = text.lines().nth(line - 1).unwrap_or_default().trim();
                panic!(
                    "{page}:{line}: bare citation of `{name}` in `{context}` (not a markdown \
                     link); regenerate with `cargo run --release --features doc --bin \
                     satex-doc`, and if it is still bare after that, `linkify_citations` in \
                     src/bin/satex-doc.rs needs to learn this citation's shape"
                );
            }
        }
    }
}

/// `{{run: ...}}` transcripts are real `satex` output against this checkout,
/// on this machine, so without `redact_paths` (in src/bin/satex-doc.rs) they
/// would embed this machine's absolute paths verbatim: where the checkout
/// sits, `$HOME`, a personal or per-year texmf tree. That makes the
/// committed page wrong for every other reader, and is why
/// `generated_docs_are_up_to_date` cannot pass from a worktree whose
/// checkout path differs. Guards the whole generated set at once, not one
/// page, against any of that leaking back in.
#[test]
fn generated_docs_have_no_machine_specific_paths() {
    let checkout = std::env::current_dir().expect("current directory");
    let checkout = checkout.display().to_string();
    let home_re = Regex::new(r"(?:^|[^~\w])(/home/[A-Za-z0-9_.-]+)").unwrap();
    let user = std::env::var("USER").or_else(|_| std::env::var("LOGNAME")).ok();

    let mut violations = Vec::new();
    for page in GENERATED_PAGES {
        let text = fs::read_to_string(page).unwrap_or_else(|e| panic!("{page}: {e}"));
        for (n, line) in text.lines().enumerate() {
            if line.contains(&checkout) {
                violations.push(format!("{page}:{}: this checkout's own path: {line}", n + 1));
            }
            if let Some(m) = home_re.find(line) {
                violations.push(format!("{page}:{}: an absolute `/home` path ({}): {line}", n + 1, m.as_str().trim()));
            }
            if let Some(user) = &user
                && !user.is_empty()
                && line.contains(user.as_str())
            {
                violations.push(format!("{page}:{}: the current user's name (`{user}`): {line}", n + 1));
            }
        }
    }
    assert!(
        violations.is_empty(),
        "generated pages contain machine-specific paths; `redact_paths` in \
         src/bin/satex-doc.rs needs to cover this shape too, then regenerate with \
         `cargo run --release --features doc --bin satex-doc`:\n{}",
        violations.join("\n")
    );
}
